import{_ as t}from"./chunks/workspace-overview.Cq8f3f8N.js";import{_ as a,o,c as r,a2 as i}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"en_US/01-getting-started.md","filePath":"en_US/01-getting-started.md"}'),n={name:"en_US/01-getting-started.md"};function s(l,e,d,c,p,h){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>Install GridSubStudio, create or open a project, and complete a first review pass.</p><h2 id="what-you-can-do-on-this-page" tabindex="-1">What you can do on this page <a class="header-anchor" href="#what-you-can-do-on-this-page" aria-label="Permalink to &quot;What you can do on this page&quot;">​</a></h2><ul><li>Start the desktop app and create a project folder.</li><li>Open existing projects or legacy CSV workspaces.</li><li>Recognize the main editing areas.</li><li>Learn the basic review workflow and essential shortcuts.</li></ul><h2 id="install-and-start-gridsubstudio" tabindex="-1">Install and start GridSubStudio <a class="header-anchor" href="#install-and-start-gridsubstudio" aria-label="Permalink to &quot;Install and start GridSubStudio&quot;">​</a></h2><p>GridSubStudio provides a Windows x64 installer and a macOS Apple Silicon test build. Both use the same project and subtitle editing workflow. Choose the package for your platform. The current Mac test build requires <strong>macOS 27.0 or later</strong>; an Intel Mac package is not available. End users do not need Python, Node.js, or Rust. The manual site is documentation, not the editor.</p><h3 id="install-on-windows" tabindex="-1">Install on Windows <a class="header-anchor" href="#install-on-windows" aria-label="Permalink to &quot;Install on Windows&quot;">​</a></h3><p>Run the <code>.msi</code> supplied by your distributor, then start GridSubStudio from the Start menu or application shortcut.</p><h3 id="install-on-macos" tabindex="-1">Install on macOS <a class="header-anchor" href="#install-on-macos" aria-label="Permalink to &quot;Install on macOS&quot;">​</a></h3><ol><li>Download and open the Apple Silicon <code>.dmg</code>.</li><li>Drag <strong>GridSubStudio.app</strong> into <strong>Applications</strong>.</li><li>Eject the disk image and launch GridSubStudio from Applications. Its installation directory must be writable for updates.</li></ol><h3 id="first-launch-on-macos-bypass-the-gatekeeper-block" tabindex="-1">First launch on macOS: bypass the Gatekeeper block <a class="header-anchor" href="#first-launch-on-macos-bypass-the-gatekeeper-block" aria-label="Permalink to &quot;First launch on macOS: bypass the Gatekeeper block&quot;">​</a></h3><p>The current Mac test build has no Apple Developer ID signature or notarization. macOS may report an unidentified developer or that Apple cannot check the app for malicious software. After confirming the package is from a trusted distributor and has not been modified, allow this specific app:</p><ol><li>Try launching <strong>GridSubStudio</strong> from Applications and dismiss the block.</li><li>Open <strong>System Settings → Privacy &amp; Security</strong>, find the message about GridSubStudio, and select <strong>Open Anyway</strong>.</li><li>Authenticate if requested, then select <strong>Open</strong> in the confirmation.</li></ol><p>macOS remembers this exception. If the button is missing, try launching the app again and revisit settings; managed Macs may require an administrator. For a damaged-file warning, download again and compare the distributor&#39;s checksum. Do not treat a warning that an app will damage your computer as a routine notarization warning.</p><p>This creates an exception for GridSubStudio without disabling Gatekeeper globally. See <a href="https://support.apple.com/en-us/102445" target="_blank" rel="noreferrer">Apple&#39;s instructions</a>.</p><p>Keep projects in a normal writable folder. Avoid temporary download folders, read-only media, and cloud locations that are currently reporting sync conflicts.</p><h2 id="create-a-subtitle-project" tabindex="-1">Create a subtitle project <a class="header-anchor" href="#create-a-subtitle-project" aria-label="Permalink to &quot;Create a subtitle project&quot;">​</a></h2><ol><li>Click <strong>New Project</strong>.</li><li>Choose or create an empty project folder.</li><li>Give the project a clear name.</li><li>Import original subtitles, translated subtitles, and videos as available.</li><li>Set quality limits, target language, and the spellcheck dictionary.</li><li>Review filename-to-episode mapping, then click <strong>Confirm</strong>.</li></ol><p>A project normally contains <code>project.json</code>, <code>workspace.csv</code>, resource folders, exports, translation backups, and a glossary. Do not move individual managed files outside the project folder.</p><h2 id="open-an-existing-project" tabindex="-1">Open an existing project <a class="header-anchor" href="#open-an-existing-project" aria-label="Permalink to &quot;Open an existing project&quot;">​</a></h2><p>Click <strong>Open Project</strong> and choose the project folder or its <code>project.json</code>. GridSubStudio restores the workspace, project resources, selected episode, and relevant view state.</p><p>Only one active app instance can edit a project at a time. If the project is locked by another window, return to that window and close the project normally before reopening it.</p><h2 id="open-and-migrate-a-legacy-csv" tabindex="-1">Open and migrate a legacy CSV <a class="header-anchor" href="#open-and-migrate-a-legacy-csv" aria-label="Permalink to &quot;Open and migrate a legacy CSV&quot;">​</a></h2><p>Use <strong>Open CSV</strong> for a standalone workspace created by an older workflow. Legacy CSV mode supports editing, saving, <strong>Save As</strong>, and XLSX export, but project-only features require migration.</p><p>To migrate, create a project and import the CSV/subtitle resources into it. Keep the original CSV as a backup until the new project has been saved and checked.</p><h2 id="learn-the-workspace" tabindex="-1">Learn the workspace <a class="header-anchor" href="#learn-the-workspace" aria-label="Permalink to &quot;Learn the workspace&quot;">​</a></h2><p><img src="'+t+'" alt="GridSubStudio workspace showing search, row tools, validation, and subtitle data"></p><ul><li>The <strong>top bar</strong> contains project, import, save, export, machine translation, settings, and help actions.</li><li>The <strong>subtitle grid</strong> displays source text, translation, timing, episode, and calculated quality fields.</li><li>The <strong>video panel</strong> plays the video assigned to the current episode.</li><li>The <strong>timeline and playback controls</strong> navigate subtitle ranges and adjust timing.</li><li>The <strong>search, filters, line tools, and validation summary</strong> focus the rows that need work.</li></ul><p>Drag the divider between grid and video to redistribute space. Use <strong>Reset View</strong> if the layout becomes difficult to use.</p><h2 id="complete-a-basic-review-pass" tabindex="-1">Complete a basic review pass <a class="header-anchor" href="#complete-a-basic-review-pass" aria-label="Permalink to &quot;Complete a basic review pass&quot;">​</a></h2><ol><li>Select an episode and play its video.</li><li>Click a subtitle row to focus it.</li><li>Edit the source or translation cell.</li><li>Check the subtitle against video and audio.</li><li>Adjust timing when required.</li><li>Resolve validation and spelling alerts.</li><li>Save with <code>Ctrl+S</code> on Windows or <code>Command+S</code> on macOS.</li><li>Open the export wizard and verify output settings.</li></ol><h2 id="view-shortcuts-and-help" tabindex="-1">View shortcuts and help <a class="header-anchor" href="#view-shortcuts-and-help" aria-label="Permalink to &quot;View shortcuts and help&quot;">​</a></h2><p>Press <code>?</code> or choose <strong>Settings → Keyboard Shortcuts</strong>. Common shortcuts include:</p><p>In the table, <code>Ctrl</code> is the Windows modifier; use <code>Command (⌘)</code> on macOS. Use Command for multi-range selection and copy/cut/paste as well. Depending on keyboard settings, F7 may require Fn.</p><p>Exception: macOS reserves <code>Command+H</code> for hiding windows. Open Advanced Search / Replace with its button or <code>Ctrl+H</code>. See <a href="https://support.apple.com/en-us/102650" target="_blank" rel="noreferrer">Apple keyboard shortcuts</a>.</p><table tabindex="0"><thead><tr><th>Action</th><th>Shortcut</th></tr></thead><tbody><tr><td>Save</td><td><code>Ctrl+S</code></td></tr><tr><td>Undo / Redo</td><td><code>Ctrl+Z</code> / <code>Ctrl+Y</code></td></tr><tr><td>Find / Replace</td><td><code>Ctrl+F</code> / <code>Ctrl+H</code></td></tr><tr><td>Play / Pause</td><td><code>Space</code></td></tr><tr><td>Previous / Next subtitle</td><td><code>Arrow Up</code> / <code>Arrow Down</code></td></tr><tr><td>Spellchecker</td><td><code>F7</code></td></tr><tr><td>Close a floating tool</td><td><code>Esc</code></td></tr></tbody></table><p>When a cell is actively being edited, text-editing behavior takes priority over grid shortcuts.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li><strong>The app does not start:</strong> confirm the packaged desktop app was installed, rather than opening source files or the manual site.</li><li><strong>A project will not open:</strong> verify <code>project.json</code> still exists and the folder is writable.</li><li><strong>A project is locked:</strong> close the other GridSubStudio window normally.</li><li><strong>The layout is cramped:</strong> reduce <strong>UI Size</strong>, enlarge the window, or drag the workspace divider.</li></ul>',39)])])}const b=a(n,[["render",s]]);export{m as __pageData,b as default};
